// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
import type { IdentitySnapshot } from '../integrations/identity.ts';
import type { RegisteredWorkflow, WorkflowInstance } from './state.ts';
import { DEFAULT_ORGANIZATION_ID } from './identity.ts';
import { projectSummaryFields } from './summary.ts';

export class PersistenceConflictError extends Error {
  readonly code: 'CONFLICT' | 'STALE_REVISION'; constructor(
    message: string,
    code: 'CONFLICT' | 'STALE_REVISION' = 'CONFLICT',
  ) {
    super(message); this.code = code;
    this.name = 'PersistenceConflictError';
  }
}

export type CallbackClaim = 'claimed' | 'completed' | 'processing' | 'conflict';

/** A key that is absent is left as is; present and undefined (or []) clears it. */
export interface ObjectScope {
  business_unit?: string | undefined;
  department?: string | undefined;
  /** All departments of a multi-department object; `department` stays the first. */
  departments?: string[];
}

export function reassignInstanceObjectScope(
  current: WorkflowInstance,
  scope: ObjectScope,
  at: string,
): WorkflowInstance | undefined {
  const instance = clone(current);
  const next = { ...instance.task };
  const changed: Record<string, { before: unknown; after: unknown }> = Object.create(null);
  for (const field of ['business_unit', 'department', 'departments'] as const) {
    if (!(field in scope)) continue; // not sent: leave as is
    // An empty list clears the field, and is no change when it was never set.
    const value = field === 'departments' && !scope.departments?.length ? undefined : scope[field];
    if (JSON.stringify(next[field]) === JSON.stringify(value)) continue;
    changed[field] = { before: next[field], after: value };
    if (value === undefined) delete next[field];
    else next[field] = value;
  }
  if (Object.keys(changed).length === 0) return undefined;
  instance.task = next;
  instance.object = { ...instance.object, data: next };
  instance.history.push({
    at,
    type: 'task_updated',
    detail: Object.keys(changed).join(', '),
    data: changed,
    source: 'provisioning',
  });
  instance.updated_at = at;
  return instance;
}

export interface JobCheckpoint {
  organization_id: string;
  job_id: string;
  cursor?: string;
  state?: Record<string, unknown>;
  revision: number;
  lease?: { owner: string; expires_at: string };
  updated_at: string;
}

export interface WorkflowStore {
  registerWorkflow(workflow: RegisteredWorkflow): Promise<void>;
  upsertWorkflow(workflow: RegisteredWorkflow): Promise<{ created: boolean }>;
  deleteWorkflow(id: string, force?: boolean, organizationId?: string): Promise<void>;
  getWorkflow(id: string, organizationId?: string): Promise<RegisteredWorkflow | undefined>;
  getWorkflowVersion(
    id: string,
    version: number,
    organizationId?: string,
  ): Promise<RegisteredWorkflow | undefined>;
  listWorkflows(organizationId?: string): Promise<RegisteredWorkflow[]>;

  /**
   * Creates or compare-and-swaps an instance. A fetched instance carries the
   * revision that must still be current when it is saved. History and outbox
   * are embedded, so one successful write commits all three atomically.
   */
  saveInstance(instance: WorkflowInstance): Promise<void>;
  getInstance(id: string, organizationId?: string): Promise<WorkflowInstance | undefined>;
  listInstances(workflowId?: string, organizationId?: string): Promise<WorkflowInstance[]>;
  listInstancesPage(
    organizationId: string,
    workflowId: string | undefined,
    after: string | undefined,
    limit: number,
  ): Promise<{ items: WorkflowInstance[]; next_cursor?: string }>;
  listObjectInstances(organizationId: string, type: string, id: string): Promise<WorkflowInstance[]>;
  /**
   * Every instance on any of these objects, in one read (list pages). A
   * persistent store may return only the fields instanceSummary and
   * instanceResource read.
   */
  listInstancesForObjects(organizationId: string, type: string, ids: string[]): Promise<WorkflowInstance[]>;
  reassignObjectScope(
    organizationId: string,
    type: string,
    id: string,
    scope: ObjectScope,
  ): Promise<{ matched: number; updated: number }>;
  findAttachment(
    organizationId: string,
    workflowId: string,
    type: string,
    id: string,
  ): Promise<WorkflowInstance | undefined>;

  replaceIdentitySnapshot(snapshot: IdentitySnapshot): Promise<void>;
  getIdentitySnapshot(organizationId: string): Promise<IdentitySnapshot | undefined>;
  claimCallbackEvent(
    organizationId: string,
    eventId: string,
    fingerprint: string,
  ): Promise<CallbackClaim>;
  completeCallbackEvent(organizationId: string, eventId: string): Promise<void>;
  failCallbackEvent(organizationId: string, eventId: string, error: string): Promise<void>;
  getJobCheckpoint(organizationId: string, jobId: string): Promise<JobCheckpoint | undefined>;
  claimJobLease(
    organizationId: string,
    jobId: string,
    owner: string,
    leaseSeconds: number,
  ): Promise<{ acquired: boolean; checkpoint: JobCheckpoint }>;
  saveJobCheckpoint(checkpoint: JobCheckpoint, owner: string): Promise<JobCheckpoint>;
  releaseJobLease(organizationId: string, jobId: string, owner: string): Promise<void>;
}

const workflowKey = (organizationId: string, workflowId: string) =>
  `${organizationId}\u0000${workflowId}`;
const versionKey = (organizationId: string, workflowId: string, version: number) =>
  `${workflowKey(organizationId, workflowId)}\u0000${version}`;
const clone = <T>(value: T): T => structuredClone(value);

/** Copy-on-read in-memory reference adapter used by the offline test suite. */
export class InMemoryStore implements WorkflowStore {
  private workflows = new Map<string, RegisteredWorkflow>();
  private versions = new Map<string, RegisteredWorkflow>();
  private instances = new Map<string, WorkflowInstance>();
  private identity = new Map<string, IdentitySnapshot>();
  private callbacks = new Map<string, {
    fingerprint: string;
    status: 'processing' | 'completed' | 'failed';
    error?: string;
  }>();
  private jobs = new Map<string, JobCheckpoint>();

  async registerWorkflow(workflow: RegisteredWorkflow): Promise<void> {
    const key = workflowKey(workflow.organization_id, workflow.id);
    if (this.workflows.has(key)) {
      throw new PersistenceConflictError(
        `workflow "${workflow.id}" already registered in organization "${workflow.organization_id}"`,
      );
    }
    const persisted = clone({ ...workflow, version: 1 });
    this.workflows.set(key, persisted);
    this.versions.set(versionKey(workflow.organization_id, workflow.id, 1), clone(persisted));
  }

  async upsertWorkflow(workflow: RegisteredWorkflow): Promise<{ created: boolean }> {
    const key = workflowKey(workflow.organization_id, workflow.id);
    const existing = this.workflows.get(key);
    const created = !existing;
    if (existing && workflow.version !== existing.version) {
      throw new PersistenceConflictError(
        `workflow "${workflow.id}" changed concurrently (expected version ${workflow.version}, current ${existing.version})`,
        'STALE_REVISION',
      );
    }
    const version = existing ? existing.version + 1 : 1;
    const persisted = clone({ ...workflow, version });
    this.workflows.set(key, persisted);
    this.versions.set(versionKey(workflow.organization_id, workflow.id, version), clone(persisted));
    return { created };
  }

  async deleteWorkflow(
    id: string,
    force = false,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): Promise<void> {
    const key = workflowKey(organizationId, id);
    if (!this.workflows.has(key)) throw new Error(`workflow "${id}" not found`);
    const live = (await this.listInstances(id, organizationId)).length;
    if (live && !force) {
      throw new PersistenceConflictError(
        `workflow "${id}" has ${live} attached instance(s); pass force=true to delete anyway`,
      );
    }
    this.workflows.delete(key);
  }

  async getWorkflow(
    id: string,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): Promise<RegisteredWorkflow | undefined> {
    const value = this.workflows.get(workflowKey(organizationId, id));
    return value && clone(value);
  }

  async getWorkflowVersion(
    id: string,
    version: number,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): Promise<RegisteredWorkflow | undefined> {
    const value = this.versions.get(versionKey(organizationId, id, version));
    return value && clone(value);
  }

  async listWorkflows(organizationId?: string): Promise<RegisteredWorkflow[]> {
    const all = [...this.workflows.values()];
    return all
      .filter((workflow) => !organizationId || workflow.organization_id === organizationId)
      .map(clone);
  }

  async saveInstance(instance: WorkflowInstance): Promise<void> {
    const existing = this.instances.get(instance.id);
    if (existing && existing.organization_id !== instance.organization_id) {
      throw new PersistenceConflictError(`instance "${instance.id}" belongs to another organization`);
    }
    const expected = instance.revision ?? 0;
    if (existing && existing.revision !== expected) {
      throw new PersistenceConflictError(
        `instance "${instance.id}" changed concurrently (expected revision ${expected}, current ${existing.revision})`,
        'STALE_REVISION',
      );
    }
    if (!existing && expected !== 0) {
      throw new PersistenceConflictError(
        `instance "${instance.id}" does not exist at expected revision ${expected}`,
        'STALE_REVISION',
      );
    }
    if (!existing) {
      const duplicateAttachment = [...this.instances.values()].some(
        (candidate) =>
          candidate.organization_id === instance.organization_id &&
          candidate.workflow_id === instance.workflow_id &&
          candidate.object.type === instance.object.type &&
          candidate.object.id === instance.object.id,
      );
      if (duplicateAttachment) {
        throw new PersistenceConflictError(
          `workflow/object attachment already exists in organization "${instance.organization_id}"`,
        );
      }
    }
    instance.revision = expected + 1;
    this.instances.set(instance.id, clone(instance));
  }

  async getInstance(
    id: string,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): Promise<WorkflowInstance | undefined> {
    const instance = this.instances.get(id);
    return instance?.organization_id === organizationId ? clone(instance) : undefined;
  }

  async listInstances(workflowId?: string, organizationId?: string): Promise<WorkflowInstance[]> {
    return [...this.instances.values()]
      .filter(
        (instance) => (!workflowId || instance.workflow_id === workflowId) &&
          (!organizationId || instance.organization_id === organizationId),
      )
      .map(clone);
  }

  async listInstancesPage(
    organizationId: string,
    workflowId: string | undefined,
    after: string | undefined,
    limit: number,
  ): Promise<{ items: WorkflowInstance[]; next_cursor?: string }> {
    const rows = (await this.listInstances(workflowId, organizationId))
      .sort((a, b) => a.id.localeCompare(b.id))
      .filter((instance) => !after || instance.id > after)
      .slice(0, limit + 1);
    const items = rows.slice(0, limit);
    return {
      items,
      next_cursor: rows.length > limit ? items[items.length - 1]?.id : undefined,
    };
  }

  async listObjectInstances(
    organizationId: string,
    type: string,
    id: string,
  ): Promise<WorkflowInstance[]> {
    return (await this.listInstances(undefined, organizationId)).filter(
      (instance) => instance.object.type === type && instance.object.id === id,
    );
  }

  async listInstancesForObjects(
    organizationId: string,
    type: string,
    ids: string[],
  ): Promise<WorkflowInstance[]> {
    const wanted = new Set(ids);
    return (await this.listInstances(undefined, organizationId))
      .filter((instance) => instance.object.type === type && wanted.has(instance.object.id))
      .map(projectSummaryFields);
  }

  async reassignObjectScope(
    organizationId: string,
    type: string,
    id: string,
    scope: ObjectScope,
  ): Promise<{ matched: number; updated: number }> {
    const instances = Array.from(this.instances.values()).filter(
      (instance) =>
        instance.organization_id === organizationId &&
        instance.object.type === type &&
        instance.object.id === id,
    );
    const at = new Date().toISOString();
    const replacements = instances
      .map((instance) => reassignInstanceObjectScope(instance, scope, at))
      .filter((instance): instance is WorkflowInstance => instance !== undefined);
    for (const instance of replacements) instance.revision = (instance.revision ?? 0) + 1;
    for (const instance of replacements) this.instances.set(instance.id, instance);
    return { matched: instances.length, updated: replacements.length };
  }

  async findAttachment(
    organizationId: string,
    workflowId: string,
    type: string,
    id: string,
  ): Promise<WorkflowInstance | undefined> {
    return (await this.listObjectInstances(organizationId, type, id))
      .find((instance) => instance.workflow_id === workflowId);
  }

  async replaceIdentitySnapshot(snapshot: IdentitySnapshot): Promise<void> {
    this.identity.set(snapshot.organization_id, clone(snapshot));
  }

  async getIdentitySnapshot(organizationId: string): Promise<IdentitySnapshot | undefined> {
    const snapshot = this.identity.get(organizationId);
    return snapshot && clone(snapshot);
  }

  async claimCallbackEvent(
    organizationId: string,
    eventId: string,
    fingerprint: string,
  ): Promise<CallbackClaim> {
    const key = workflowKey(organizationId, eventId);
    const existing = this.callbacks.get(key);
    if (existing?.fingerprint !== undefined && existing.fingerprint !== fingerprint) return 'conflict';
    if (existing?.status === 'completed') return 'completed';
    if (existing?.status === 'processing') return 'processing';
    this.callbacks.set(key, { fingerprint, status: 'processing' });
    return 'claimed';
  }

  async completeCallbackEvent(organizationId: string, eventId: string): Promise<void> {
    const key = workflowKey(organizationId, eventId);
    const existing = this.callbacks.get(key);
    if (existing) this.callbacks.set(key, { ...existing, status: 'completed', error: undefined });
  }

  async failCallbackEvent(organizationId: string, eventId: string, error: string): Promise<void> {
    const key = workflowKey(organizationId, eventId);
    const existing = this.callbacks.get(key);
    if (existing) this.callbacks.set(key, { ...existing, status: 'failed', error });
  }

  async getJobCheckpoint(
    organizationId: string,
    jobId: string,
  ): Promise<JobCheckpoint | undefined> {
    const checkpoint = this.jobs.get(workflowKey(organizationId, jobId));
    return checkpoint && clone(checkpoint);
  }

  async claimJobLease(
    organizationId: string,
    jobId: string,
    owner: string,
    leaseSeconds: number,
  ): Promise<{ acquired: boolean; checkpoint: JobCheckpoint }> {
    const key = workflowKey(organizationId, jobId);
    const now = Date.now();
    const existing = this.jobs.get(key) ?? {
      organization_id: organizationId,
      job_id: jobId,
      revision: 0,
      updated_at: new Date(now).toISOString(),
    };
    const acquired = !existing.lease ||
      existing.lease.owner === owner ||
      new Date(existing.lease.expires_at).getTime() <= now;
    if (!acquired) return { acquired: false, checkpoint: clone(existing) };
    const checkpoint: JobCheckpoint = {
      ...existing,
      revision: existing.revision + 1,
      lease: { owner, expires_at: new Date(now + leaseSeconds * 1000).toISOString() },
      updated_at: new Date(now).toISOString(),
    };
    this.jobs.set(key, clone(checkpoint));
    return { acquired: true, checkpoint: clone(checkpoint) };
  }

  async saveJobCheckpoint(checkpoint: JobCheckpoint, owner: string): Promise<JobCheckpoint> {
    const key = workflowKey(checkpoint.organization_id, checkpoint.job_id);
    const existing = this.jobs.get(key);
    if (
      !existing || existing.revision !== checkpoint.revision ||
      existing.lease?.owner !== owner ||
      new Date(existing.lease.expires_at).getTime() <= Date.now()
    ) {
      throw new PersistenceConflictError('job checkpoint lease or revision is stale', 'STALE_REVISION');
    }
    const saved: JobCheckpoint = {
      ...clone(checkpoint),
      revision: checkpoint.revision + 1,
      lease: {
        owner,
        expires_at: new Date(Date.now() + 300_000).toISOString(),
      },
      updated_at: new Date().toISOString(),
    };
    this.jobs.set(key, clone(saved));
    return clone(saved);
  }

  async releaseJobLease(organizationId: string, jobId: string, owner: string): Promise<void> {
    const key = workflowKey(organizationId, jobId);
    const existing = this.jobs.get(key);
    if (!existing || existing.lease?.owner !== owner) return;
    const { lease: _ignored, ...released } = existing;
    this.jobs.set(key, {
      ...released,
      revision: existing.revision + 1,
      updated_at: new Date().toISOString(),
    });
  }
}

/** Back-compatible name for callers that imported the old in-memory class. */
export class Store extends InMemoryStore {}
